STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.tonic = tonic
        notes = FLATS if tonic in FLAT_TONICS else SHARPS
        name = tonic[0].upper() + tonic[1:]
        if name in notes:
            start = notes.index(name)
        elif name in SHARPS:
            start = SHARPS.index(name)
        else:
            start = FLATS.index(name)
        self._notes = notes[start:] + notes[:start]

    def chromatic(self):
        return list(self._notes)

    def interval(self, intervals):
        result = [self._notes[0]]
        pos = 0
        for step in intervals:
            pos += STEPS[step]
            result.append(self._notes[pos % 12])
        return result
